mapper.sql:
status = 1

    and (
    comp_name like concat('%', #{keyword}, '%')
    or organizer like concat('%', #{keyword}, '%')
    )


    and comp_level = #{compLevel}


    and comp_status = #{compStatus}


    and date_format(register_end, '%Y') = #{year}


    and date_format(register_end, '%m') = #{month}

mapper.select:
select
from competition
order by case comp_status when '报名中' then 1 when '即将开始' then 2 when '已结束' then 3 else 4 end, register_end asc, id desc limit #{offset}, #{pageSize}
